var position = $('#history-video').offset();  
// on scrolling of the document do something
$(document).scroll(function () {
    //the current height
    var y = $(this).scrollTop();

    //If the current Y is bigger than the element. (you scrolled beyond the element)
    if(y >= position.top){
        $("#history-video .fables-gallery-circle").addClass("fables-second-background-color fables-second-before");
    }else{
        $("#history-video .fables-gallery-circle").removeClass("fables-second-background-color fables-second-before");
    }
});


